import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.DXa1R37q.js";const y=JSON.parse('{"title":"Security and errors","description":"","frontmatter":{},"headers":[],"relativePath":"guides/security-and-errors.md","filePath":"guides/security-and-errors.md","lastUpdated":1792970147000}'),s={name:"guides/security-and-errors.md"};function n(i,e,c,d,p,u){return t(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="security-and-errors" tabindex="-1">Security and errors <a class="header-anchor" href="#security-and-errors" aria-label="Permalink to &quot;Security and errors&quot;">​</a></h1><p>Issues, Design Docs, and Repository Store use structured errors with a category, stable code, message, retryability, and bounded details or paths. Searchable errors contain <code>category</code>, <code>code</code>, <code>message</code>, <code>paths</code>, and optional <code>details</code>; they do not expose a retryability field. Branch on the code and avoid logging rejected secrets. Memory library errors are typed, but current Memory MCP errors are plain text.</p><p>A secret rejection means Memory detected a configured pattern or high-entropy candidate. Remove the secret and store only a reference to the protected credential. Resource-limit errors name the configured boundary; narrow the request or review the configuration rather than bypassing validation.</p><p>Path errors reject traversal, symlinks, unsafe components, and authority conflicts. Contention errors require waiting or inspecting owner evidence. Stale revisions require a fresh read. Stale or corrupt cache errors permit rebuilding only from valid canonical data. Unsupported platform errors require a supported deployment.</p><p>See <a href="/projects/neottia/memory/operations">Memory operations</a>, <a href="/projects/neottia/issues/operations">Issues operations</a>, <a href="/projects/neottia/design-docs/operations">Design Docs operations</a>, <a href="/projects/neottia/searchable/security">Searchable security</a>, and <a href="/projects/neottia/repository-store">Repository Store</a>.</p>',5)])])}const h=r(s,[["render",n]]);export{y as __pageData,h as default};
